	"github.com/XUJiahua/enterprise_agent/internal/action"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Reject is the batch rejection Action: submitted -> rejected.
var Reject = action.Transition{Operation: "bulk-reject.v4", From: "submitted", To: "rejected", Field: "rejectedIds"}

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	executor, err := action.New(ctx, pool)
	if err != nil {
		return nil, err
	}
	return protocol.HTTP(protocol.Routes{
		"/purchases/bulk-approve": route(executor, action.Approve),
		"/purchases/bulk-reject":  route(executor, Reject),
	}, fallback), nil
}

// route adapts one kernel Transition to the shared HTTP adapter, translating
// action.Rejection into protocol.Rejection at this boundary.
func route(executor *action.Executor, t action.Transition) protocol.Handler {
	return func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		done, replayed, err := executor.Run(ctx, u, t, key, ids)
		var denied *action.Rejection
		if errors.As(err, &denied) {
